// Validation suite for /book/ — the public mirror of the Valorant training map
// book. The book HTML is generated by valorant-mapbook/mirror.py and copied
// into static/book/, so the thing most likely to break silently is the /book/
// prefix on every relative link (a bare "style.css" would 404 from /book/).
// Mirrors a few checks from landing.test.js: one h1, no horizontal scroll, and
// the PDF actually served as a PDF.
const { test, expect } = require('@playwright/test');

const WIDTHS = [1440, 768, 375];
// Maps in the published edition, not the manifest: the book ships as the brief
// edition (Bind + Haven), so the site only has these pages. Add the rest back
// here when a full edition is published.
const MAP_SLUGS = ['bind', 'haven'];

test.describe('Valorant map book landing page', () => {
  test('no horizontal scroll, exactly one h1, at every width', async ({ page }) => {
    for (const w of WIDTHS) {
      await page.setViewportSize({ width: w, height: 900 });
      await page.goto('/book/', { waitUntil: 'load' });
      const overflow = await page.evaluate(
        () => document.documentElement.scrollWidth > window.innerWidth
      );
      expect(overflow, `horizontal scroll at ${w}px`).toBe(false);
      expect(await page.locator('h1').count(), `h1 count at ${w}px`).toBe(1);
    }
  });

  test('every site link resolves from /book/ (no bare relative URLs)', async ({ page, request }) => {
    await page.goto('/book/', { waitUntil: 'load' });
    // Bare relatives ("style.css", "../pages/p-01.png") are the failure mode:
    // they only work if the reader happens to be at the right depth. The site
    // chrome (header/footer of the Hugo page) links to other site pages, so
    // rooted URLs are fine — what must not exist is an unprefixed relative.
    const hrefs = await page.evaluate(() =>
      Array.from(document.querySelectorAll('a[href]'))
        .map((a) => a.getAttribute('href'))
        .filter((h) => h && !h.startsWith('#') && !/^[a-z]+:/i.test(h) && !h.startsWith('//'))
    );
    expect(hrefs.length, 'links found on the landing page').toBeGreaterThan(0);
    for (const href of hrefs) {
      expect(href, `bare relative link ${href}`).toMatch(/^\//);
      const res = await request.get(href);
      expect(res.status(), `${href} status`).toBe(200);
    }
    // The book's own assets must all live under /book/.
    const bookLinks = hrefs.filter((h) => /(style\.css|\.pdf|history\.html|\/map\/|\/pages\/)/.test(h));
    // A short edition legitimately has few links (PDF + history + 2 map pages);
    // the point is that whatever exists lives under /book/.
    expect(bookLinks.length, 'book asset links').toBeGreaterThanOrEqual(3);
    bookLinks.forEach((h) => expect(h).toMatch(/^\/book\//));
  });

  test('every published map page loads with its images', async ({ page }) => {
    for (const slug of MAP_SLUGS) {
      const res = await page.goto(`/book/map/${slug}.html`, { waitUntil: 'load' });
      expect(res.status(), `${slug} status`).toBe(200);
      expect(await page.locator('h2').first().innerText()).toBeTruthy();
      const broken = await page.evaluate(() =>
        Array.from(document.images).filter((i) => i.complete && i.naturalWidth === 0).length
      );
      expect(broken, `${slug} broken images`).toBe(0);
      // Read from the live DOM, not the attribute: the browser resolves
      // "../pages/p-03.png" against the page URL, the same way the served
      // file would be resolved by any other browser.
      const sheetSrcs = await page.evaluate(() =>
        Array.from(document.querySelectorAll('.sheet img')).map((i) =>
          new URL(i.getAttribute('src'), document.baseURI).pathname
        )
      );
      expect(sheetSrcs.length, `${slug} sheets`).toBe(4);
      sheetSrcs.forEach((src) => expect(src).toMatch(/^\/book\/pages\/p-\d+\.png$/));
    }
  });

  test('PDF is served and the licence disclaimer is present', async ({ page, request }) => {
    const pdf = await request.get('/book/tactical-map-book.pdf');
    expect(pdf.status()).toBe(200);
    expect(pdf.headers()['content-type']).toContain('pdf');

    await page.goto('/book/', { waitUntil: 'load' });
    const legal = await page.locator('#legal').innerText();
    expect(legal).toContain('not for sale');
    expect(legal).toContain('Riot Games');
    expect(legal).toContain('Icarus');
  });
});
